            "claim": "The pMap function does not properly handle the case where a mapper returns pMapSkip for an item that has already been processed and skipped, leading to incorrect result ordering when multiple items are skipped.",
            "path": "index.js",
            "start_line": 105,
            "end_line": 113,
            "evidence": "for (const [index, value] of result.entries()) {
				if (skippedIndexesMap.get(index) === pMapSkip) {
					continue;
				}

				pureResult.push(value);
			}",
            "reproduction": {
                "code": "const {default: pMap, pMapSkip} = await load('./index.js');

async function mapper(value, index) {
  if (index === 1) {
    return pMapSkip;
  }
  return value * 2;
}

const input = [1, 2, 3];
const result = await pMap(input, mapper);
assert.deepStrictEqual(result, [2, 6]);"
            }
        }
